+	return rc;
 }

  */
 static ssize_t smk_write_doi(struct file *file, const char __user *buf,
 			     size_t count, loff_t *ppos)
 {
 	char temp[80];
 	unsigned long u;

 	if (!smack_privileged(CAP_MAC_ADMIN))
 		return -EPERM;

 	if (count >= sizeof(temp) || count == 0)
 		return -EINVAL;

 	if (copy_from_user(temp, buf, count) != 0)
 		return -EFAULT;

 	temp[count] = '\0';

 	if (kstrtoul(temp, 10, &u))
 		return -EINVAL;

 	if (u == CIPSO_V4_DOI_UNKNOWN || u > U32_MAX)
 		return -EINVAL;
-	smk_cipso_doi_value = u;
-
-	smk_cipso_doi();

-	return count;
+	return smk_cipso_doi(u, GFP_KERNEL) ? : count;
 }

  */
 int __init init_smk_fs(void)
 {
 	int err;
 	int rc;
+	struct netlbl_audit nai;

 	if (smack_enabled == 0)
 		return 0;

 	err = smk_init_sysfs();
 	if (err)
 		printk(KERN_ERR "smackfs: sysfs mountpoint problem.\n");

 	err = register_filesystem(&smk_fs_type);
 	if (!err) {
 		smackfs_mount = kern_mount(&smk_fs_type);
 		if (IS_ERR(smackfs_mount)) {
 			printk(KERN_ERR "smackfs:  could not mount!\n");
 			err = PTR_ERR(smackfs_mount);
 			smackfs_mount = NULL;
 		}
 	}

-	smk_cipso_doi();
+	smk_netlabel_audit_set(&nai);
+	(void) netlbl_cfg_map_del(NULL, PF_INET, NULL, NULL, &nai);
+	(void) smk_cipso_doi(SMACK_CIPSO_DOI_DEFAULT,
+			     GFP_KERNEL | __GFP_NOFAIL);
 	smk_unlbl_ambient(NULL);

 	rc = smack_populate_secattr(&smack_known_floor);
 	if (err == 0 && rc < 0)
 		err = rc;
 	rc = smack_populate_secattr(&smack_known_hat);
 	if (err == 0 && rc < 0)
 		err = rc;
 	rc = smack_populate_secattr(&smack_known_huh);
 	if (err == 0 && rc < 0)
 		err = rc;
 	rc = smack_populate_secattr(&smack_known_star);
 	if (err == 0 && rc < 0)
 		err = rc;
 	rc = smack_populate_secattr(&smack_known_web);
 	if (err == 0 && rc < 0)
 		err = rc;

 	return err;
 }
