/**
 * smk_read_ambient - read() for /smack/ambient
 * @filp: file pointer, not actually used
 * @buf: where to put the result
 * @cn: maximum to send along
 * @ppos: where to start
 *
 * Returns number of bytes read or error code, as appropriate
 */
static ssize_t smk_read_ambient(struct file *filp, char __user *buf,
				size_t cn, loff_t *ppos)
{
	ssize_t rc;
	char out[SMK_LABELLEN];
	int asize;

	if (*ppos != 0)
		return 0;
	/*
	 * Being careful to avoid a problem in the case where
	 * smack_net_ambient gets changed in midstream.
	 * Since smack_net_ambient is always set with a value
	 * from the label list, including initially, and those
	 * never get freed, the worst case is that the pointer
	 * gets changed just after this strncpy, in which case
	 * the value passed up is incorrect. Locking around
	 * smack_net_ambient wouldn't be any better than this
	 * copy scheme as by the time the caller got to look
	 * at the ambient value it would have cleared the lock
	 * and been changed.
	 */
	strncpy(out, smack_net_ambient, SMK_LABELLEN);
	asize = strlen(out) + 1;

	if (cn < asize)
		return -EINVAL;

	rc = simple_read_from_buffer(buf, cn, ppos, out, asize);

	return rc;
}

/**
 * smk_write_ambient - write() for /smack/ambient
 * @filp: file pointer, not actually us

        Please output the result in the following format:
        Reason: <text>
        Result: <yes or no>

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The `smk_cipso_doi()` function did not properly delete the old CIPSO DOI definition and its default mapping before attempting to re-add a previously used DOI value. When a DOI value that had been used earlier was written again, the old DOI entry still existed in the CIPSO subsystem, causing `netlbl_cfg_cipsov4_add()` to fail with error -17 (EEXIST). Since the old default map had already been removed before the new DOI attempt, the system ended up with no IPv4 default mapping, disabling networking for non-ambient labels. Additionally, concurrent writes to `/smack/doi` were not serialized, potentially causing inconsistent states.

        Commit message:
        smack: /smack/doi: accept previously used values
MIME-Version: 1.0
Content-Type: text/plain; charset=UTF-8
Content-Transfer-Encoding: 8bit

Writing to /smack/doi a value that has ever been
written there in the past disables networking for
non-ambient labels.
E.g.

    # cat /smack/doi
